using Azure.Search.Documents;
using Azure.Search.Documents.Models;

public class AzureHybridSearchService
{
    private readonly SearchClient _searchClient;

    public AzureHybridSearchService(SearchClient searchClient)
    {
        _searchClient = searchClient;
    }

    public async Task<List<SearchResultDoc>> SearchHybridAsync(
        string searchText,
        ReadOnlyMemory<float> searchVector,
        string tenantId,
        int topCount = 5,
        CancellationToken ct = default)
    {
        var options = new SearchOptions
        {
            Filter = $"TenantId eq '{tenantId}'",
            Size = topCount,
            QueryType = SearchQueryType.Semantic,
            SemanticSearch = new SemanticSearchOptions
            {
                SemanticConfigurationName = "default-semantic-config",
                QueryCaption = new QueryCaption(QueryCaptionType.Extractive)
            }
        };

        // Configure dense vector query
        options.VectorSearch = new VectorSearchOptions();
        options.VectorSearch.Queries.Add(new VectorizedQuery(searchVector)
        {
            KNearestNeighborsCount = 50,
            Fields = { "Embedding" }
        });

        // Azure AI Search automatically combines BM25 searchText and Embedding vector query using RRF
        SearchResults<SearchDocument> response = await _searchClient.SearchAsync<SearchDocument>(
            searchText,
            options,
            ct);

        var results = new List<SearchResultDoc>();
        await foreach (SearchResult<SearchDocument> result in response.GetResultsAsync())
        {
            results.Add(new SearchResultDoc
            {
                Id = result.Document["Id"].ToString()!,
                Content = result.Document["Content"].ToString()!,
                Score = result.Score ?? 0.0,
                RerankerScore = result.SemanticSearch?.RerankerScore
            });
        }

        return results;
    }
}
